package cn.zhuatech.aiops.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ChangeFailureRiskService{public Result evaluate(Request r){int risk=Math.min(30,r.affectedServices()*5)+Math.min(20,r.changedComponents()*2)+Math.min(25,r.relatedIncidents30Days()*5);List<String> reasons=new ArrayList<>();if(r.testPassRate()<90){risk+=25;reasons.add("自动化测试通过率不足");}if(!r.rollbackReady()){risk+=30;reasons.add("回滚方案未就绪");}if(r.peakWindow()){risk+=20;reasons.add("变更位于业务高峰窗口");}if(r.dependencyChanged()){risk+=15;reasons.add("包含外部依赖变更");}risk=Math.min(100,risk);String status=risk>=70?"BLOCK":risk>=35?"REVIEW":"LOW_RISK";if(reasons.isEmpty())reasons.add("变更验证和恢复条件正常");return new Result(risk,status,reasons);}
 public record Request(@Min(1) int affectedServices,@Min(1) int changedComponents,@DecimalMin("0") @DecimalMax("100") double testPassRate,@Min(0) int relatedIncidents30Days,@NotNull Boolean rollbackReady,@NotNull Boolean peakWindow,@NotNull Boolean dependencyChanged){}public record Result(int failureRisk,String status,List<String> reasons){} }
